examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
private let registry = MonarchStatusRegistry([
    {{statuses.0.id}}: MonarchStatusDefinition({{statuses.0.label}}, tone: {{statuses.0.tone|tone}}),
    {{statuses.1.id}}: MonarchStatusDefinition({{statuses.1.label}}, tone: {{statuses.1.tone|tone}}),
    {{statuses.2.id}}: MonarchStatusDefinition({{statuses.2.label}}, tone: {{statuses.2.tone|tone}}),
    {{statuses.3.id}}: MonarchStatusDefinition({{statuses.3.label}}, tone: {{statuses.3.tone|tone}}),
    {{statuses.4.id}}: MonarchStatusDefinition({{statuses.4.label}}, tone: {{statuses.4.tone|tone}}),
    {{statuses.5.id}}: MonarchStatusDefinition({{statuses.5.label}}, tone: {{statuses.5.tone|tone}}),
])
private let calendar: Calendar = {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: {{timeZone}}) ?? .gmt
    return calendar
}()

examples.setup:
@Environment(\.monarchTheme) private var theme
private let registry = MonarchStatusRegistry([
    "parked": MonarchStatusDefinition("Parked", tone: .neutral),
    "no_website": MonarchStatusDefinition("No website", tone: .info),
    "no_dns": MonarchStatusDefinition("No DNS", tone: .warning),
    "keep": MonarchStatusDefinition("Keep", tone: .success),
    "review": MonarchStatusDefinition("Review", tone: .info),
    "let_lapse": MonarchStatusDefinition("Let lapse", tone: .danger),
])
private let calendar: Calendar = {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
    return calendar
}()
